create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now());
create table if not exists public.utm_values(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('campaign_name','event_name')),value text not null,label text not null,active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id),unique(kind,value));
create table if not exists public.generated_links(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),created_by uuid not null references auth.users(id) on delete cascade,channel text not null,destination_url text,generated_url text not null,form_data jsonb not null default '{}'::jsonb);
create index if not exists generated_links_user_date on public.generated_links(created_by,created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id) values(new.id) on conflict do nothing;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.normalize_utm_value() returns trigger language plpgsql as $$begin new.value:=trim(both '_' from regexp_replace(regexp_replace(lower(trim(coalesce(new.value,new.label))),'[^a-z0-9]+','_','g'),'_+','_','g'));new.label:=trim(new.label);new.created_by:=coalesce(new.created_by,auth.uid());return new;end$$;
drop trigger if exists normalize_utm_value on public.utm_values;create trigger normalize_utm_value before insert or update on public.utm_values for each row execute procedure public.normalize_utm_value();
alter table public.profiles enable row level security;alter table public.utm_values enable row level security;alter table public.generated_links enable row level security;
create policy "read own profile" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "read active values" on public.utm_values for select to authenticated using(active or public.is_admin());
create policy "admin inserts values" on public.utm_values for insert to authenticated with check(public.is_admin());
create policy "admin updates values" on public.utm_values for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read own links" on public.generated_links for select to authenticated using(created_by=auth.uid() or public.is_admin());
create policy "insert own links" on public.generated_links for insert to authenticated with check(created_by=auth.uid());
create policy "delete own links" on public.generated_links for delete to authenticated using(created_by=auth.uid() or public.is_admin());
grant usage on schema public to authenticated;grant select on public.profiles to authenticated;grant select,insert,update on public.utm_values to authenticated;grant select,insert,delete on public.generated_links to authenticated;
create or replace function public.admin_clear_generated_links() returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Admin access required';end if;delete from public.generated_links;end$$;grant execute on function public.admin_clear_generated_links() to authenticated;
insert into public.utm_values(kind,label,value) values('campaign_name','ongoing','ongoing'),('campaign_name','hr','hr'),('campaign_name','make_the_future','make_the_future'),('campaign_name','shape_the_future','shape_the_future'),('campaign_name','securing_tomorrow','securing_tomorrow'),('campaign_name','return_on_responsibility','return_on_responsibility'),('campaign_name','defensie','defensie'),('campaign_name','votexy','votexy'),('campaign_name','up2date','up2date'),('campaign_name','bnw','bnw'),('campaign_name','tech_belgium','tech_belgium'),('campaign_name','make_ai_work','make_ai_work'),('event_name','jaarevent_vlaanderen','jaarevent_vlaanderen'),('event_name','pitching_session_new_members','pitching_session_new_members'),('event_name','women_in_tech','women_in_tech'),('event_name','connect_it','connect_it'),('event_name','corporate_event','corporate_event') on conflict(kind,value) do nothing;
